def make_lattice(h,w,rs,cs,bg,line,nodes):
    g=[[bg]*w for _ in range(h)]
    for r in rs:
        for c in range(w): g[r][c]=line
    for c in cs:
        for r in range(h): g[r][c]=line
    for i,r in enumerate(rs):
        for j,c in enumerate(cs): g[r][c]=nodes[i][j]
    return g

